import React,{useEffect,useMemo,useRef,useState} from 'react';
import {AccessibilityInfo,Pressable,StyleSheet,Text,View} from 'react-native';
import {Canvas,Fill,Shader,Skia,ImageShader,ColorType,AlphaType} from '@shopify/react-native-skia';
import {Gesture,GestureDetector,GestureHandlerRootView} from 'react-native-gesture-handler';
import {createWater,heightPixels,GRID_X,GRID_Z,disturb,moveBall,resetWater,stepWater,waterPoint,waterUniforms,WATER_H,WATER_W} from './waterMath';
import {WATER_SHADER} from './waterShader';
const effect=Skia.RuntimeEffect.Make(WATER_SHADER);
export function WaterTank({reducedMotion=false}:{reducedMotion?:boolean}){
 const state=useRef(createWater());const [width,setWidth]=useState(WATER_W);const height=width*WATER_H/WATER_W;
 const [image,setImage]=useState<ReturnType<typeof Skia.Image.MakeImage>|null>(null);
 const [uniforms,setUniforms]=useState(()=>waterUniforms(state.current,width,height));const [paused,setPaused]=useState(false),[slow,setSlow]=useState(false),[systemReduce,setSystemReduce]=useState(false);
 const latest=useRef({width,height,paused,slow,reduce:reducedMotion||systemReduce});latest.current={width,height,paused,slow,reduce:reducedMotion||systemReduce};
 useEffect(()=>{let alive=true;AccessibilityInfo.isReduceMotionEnabled().then(v=>{if(alive)setSystemReduce(v);}).catch(()=>{});const sub=AccessibilityInfo.addEventListener('reduceMotionChanged',setSystemReduce);return()=>{alive=false;sub.remove();};},[]);
 useEffect(()=>{let raf=0,last=0;const draw=(now:number)=>{const p=latest.current;const dt=last?Math.min(.05,(now-last)/1000):0;last=now;if(!p.paused&&!p.reduce)stepWater(state.current,dt*(p.slow?.2:1));const data=Skia.Data.fromBytes(heightPixels(state.current));setImage(Skia.Image.MakeImage({width:GRID_X,height:GRID_Z,colorType:ColorType.RGBA_8888,alphaType:AlphaType.Opaque},data,GRID_X*4));setUniforms(waterUniforms(state.current,p.width,p.height));raf=requestAnimationFrame(draw);};raf=requestAnimationFrame(draw);return()=>cancelAnimationFrame(raf);},[]);
 const pan=useMemo(()=>Gesture.Pan().runOnJS(true).minDistance(0).onBegin(e=>{const p=waterPoint(e.x,e.y,latest.current.width,latest.current.height);moveBall(state.current,p.x,p.z);}).onUpdate(e=>{const p=waterPoint(e.x,e.y,latest.current.width,latest.current.height);moveBall(state.current,p.x,p.z);}),[]);
 const action=(name:string)=>{const s=state.current;if(name==='increment')moveBall(s,s.x+.15,s.z);else if(name==='decrement')moveBall(s,s.x-.15,s.z);};
 if(!effect)return <Text accessibilityRole="alert">Water renderer unavailable: shader compilation failed.</Text>;
 return <GestureHandlerRootView style={styles.root} onLayout={e=>setWidth(Math.max(100,Math.min(WATER_W,e.nativeEvent.layout.width)))}><GestureDetector gesture={pan}><View accessible accessibilityRole="adjustable" accessibilityLabel="Interactive water tank" accessibilityHint="Drag across the pool to move the submerged ball. Wave, pause and reset controls are below." accessibilityActions={[{name:'increment',label:'Move ball right'},{name:'decrement',label:'Move ball left'}]} onAccessibilityAction={e=>action(e.nativeEvent.actionName)} style={{width,height}}><Canvas style={{width,height}}><Fill>{image?<Shader source={effect} uniforms={uniforms}><ImageShader image={image} tx="clamp" ty="clamp" fit="none" sampling={{filter:0,mipmap:0}}/></Shader>:null}</Fill></Canvas></View></GestureDetector><View style={styles.controls}>{[
 ['Wave',()=>disturb(state.current,0,0,.04)],
 [paused?'Resume':'Pause',()=>setPaused(v=>!v)],
 [slow?'Slow on':'Slow motion',()=>setSlow(v=>!v)],
 ['Reset',()=>resetWater(state.current)],
 ].map(([label,fn])=><Pressable key={label as string} accessibilityRole="button" onPress={fn as ()=>void} style={styles.button}><Text style={styles.label}>{label as string}</Text></Pressable>)}</View></GestureHandlerRootView>;
}
const styles=StyleSheet.create({root:{width:'100%',alignItems:'center'},controls:{flexDirection:'row',flexWrap:'wrap',gap:8,justifyContent:'center'},button:{minHeight:44,paddingHorizontal:12,borderWidth:1,borderColor:'#b8cbc6',borderRadius:8,justifyContent:'center'},label:{fontSize:12,color:'#315954',fontFamily:'Geist'}});

/** Linear shallow-water heightfield with reflecting pool walls. No breaking waves or spray. */
export const WATER_W=380,WATER_H=410,GRID_X=64,GRID_Z=48;
export type WaterState={time:number,x:number,z:number,h:Float32Array,v:Float32Array,next:Float32Array,acc:number};
export function createWater():WaterState{const s={time:0,x:.22,z:.08,h:new Float32Array(GRID_X*GRID_Z),v:new Float32Array(GRID_X*GRID_Z),next:new Float32Array(GRID_X*GRID_Z),acc:0};disturb(s,-.4,-.25,.012);return s;}
export function disturb(s:WaterState,x:number,z:number,amplitude=.022){
 // A positive and negative lobe, so disturbances do not add water volume.
 let mean=0;const bump=new Float32Array(s.h.length);
 for(let j=0;j<GRID_Z;j++)for(let i=0;i<GRID_X;i++){const dx=(i/(GRID_X-1)*2.5-1.25-x),dz=(j/(GRID_Z-1)*1.9-.95-z),r2=dx*dx+dz*dz;const val=amplitude*(1-r2/.018)*Math.exp(-r2/.018);bump[j*GRID_X+i]=val;mean+=val;}
 mean/=bump.length;for(let i=0;i<bump.length;i++)s.h[i]+=bump[i]-mean;
}
export function moveBall(s:WaterState,x:number,z:number){
 if(!Number.isFinite(x)||!Number.isFinite(z))return;
 const nx=Math.max(-.94,Math.min(.94,x)),nz=Math.max(-.64,Math.min(.64,z));const dx=nx-s.x,dz=nz-s.z,d=Math.hypot(dx,dz);
 if(d>.003){const strength=Math.min(.025,d*.12);disturb(s,nx+dx/Math.max(d,.001)*.12,nz+dz/Math.max(d,.001)*.12,strength);disturb(s,s.x-dx/Math.max(d,.001)*.10,s.z-dz/Math.max(d,.001)*.10,-strength*.65);}
 s.x=nx;s.z=nz;
}
export function stepWater(s:WaterState,dt:number){
 s.acc+=Math.max(0,Math.min(.05,dt));const step=1/120,dx=2.5/(GRID_X-1),dz=1.9/(GRID_Z-1),c2=.32;
 while(s.acc>=step){
  for(let j=0;j<GRID_Z;j++)for(let i=0;i<GRID_X;i++){const k=j*GRID_X+i,h=s.h[k];const left=s.h[j*GRID_X+Math.max(0,i-1)],right=s.h[j*GRID_X+Math.min(GRID_X-1,i+1)],up=s.h[Math.max(0,j-1)*GRID_X+i],down=s.h[Math.min(GRID_Z-1,j+1)*GRID_X+i];s.v[k]=(s.v[k]+c2*((left+right-2*h)/(dx*dx)+(up+down-2*h)/(dz*dz))*step)*Math.exp(-.65*step);s.next[k]=h+s.v[k]*step;}
  const old=s.h;s.h=s.next;s.next=old;s.time+=step;s.acc-=step;
 }
}
export function resetWater(s:WaterState){Object.assign(s,createWater());}
/** Two-byte signed height encoding, exact same data on Skia and WebGL. */
export function heightPixels(s:WaterState){const p=new Uint8Array(s.h.length*4);for(let i=0;i<s.h.length;i++){const q=Math.round((Math.max(-.12,Math.min(.12,s.h[i]))/.24+.5)*65535);p[i*4]=q>>8;p[i*4+1]=q&255;p[i*4+2]=0;p[i*4+3]=255;}return p;}
export function waterUniforms(s:WaterState,width:number,height:number){return{resolution:[width,height],clock:s.time,ball:[s.x,-.31,s.z]};}
// Matching camera projection for pointer -> water-plane intersections.
export function waterPoint(x:number,y:number,width:number,height:number){
 const eye=[2.7,2.5,3.6],target=[0,-.22,0];const norm=(a:number[])=>{const l=Math.hypot(...a);return a.map(v=>v/l);};const f=norm(target.map((v,i)=>v-eye[i]));const r=norm([-f[2],0,f[0]]);const u=[r[1]*f[2]-r[2]*f[1],r[2]*f[0]-r[0]*f[2],r[0]*f[1]-r[1]*f[0]];
 const px=(x/width*2-1)*width/height,py=1-y/height*2;const d=norm(f.map((v,i)=>v*2.8+r[i]*px+u[i]*py));const t=-eye[1]/d[1];return{x:eye[0]+d[0]*t,z:eye[2]+d[2]*t};
}

/** Original single-pass optics renderer shared by Skia SkSL and WebGL.
 * Linear surface waves, Snell refraction and Schlick Fresnel. Caustic intensity is a
 * local focusing estimate; this is not path-traced light transport or splashing fluid.
 */
export const WATER_SHADER=`
uniform float2 resolution;
uniform float clock;
uniform float3 ball;
uniform shader heightmap;
float heightAt(float2 p){
 float2 uv=clamp((p+float2(1.25,.95))/float2(2.5,1.9),float2(0.0),float2(1.0));
 // Decode before interpolation: interpolating separately encoded bytes creates discontinuities.
 float2 q=uv*float2(63.0,47.0),lo=floor(q),f=fract(q);
 float2 a=heightmap.eval(lo+float2(.5,.5)).rg;
 float2 b=heightmap.eval(lo+float2(1.5,.5)).rg;
 float2 c=heightmap.eval(lo+float2(.5,1.5)).rg;
 float2 d=heightmap.eval(lo+float2(1.5,1.5)).rg;
 float ha=dot(a,float2(65280.0,255.0))/65535.0;
 float hb=dot(b,float2(65280.0,255.0))/65535.0;
 float hc=dot(c,float2(65280.0,255.0))/65535.0;
 float hd=dot(d,float2(65280.0,255.0))/65535.0;
 return (mix(mix(ha,hb,f.x),mix(hc,hd,f.x),f.y)-.5)*.24;
}
float3 normalAt(float2 p){float e=0.008;return normalize(float3(heightAt(p-float2(e,0.0))-heightAt(p+float2(e,0.0)),2.0*e,heightAt(p-float2(0.0,e))-heightAt(p+float2(0.0,e))));}
float3 sky(float3 d){
 float3 c=mix(float3(0.64,0.77,0.84),float3(0.24,0.44,0.57),clamp(d.y,0.0,1.0));
 float3 sun=normalize(float3(-0.45,1.0,0.4));
 c+=float3(1.0,0.91,0.71)*pow(max(0.0,dot(d,sun)),420.0)*2.5;
 // Broad skylight reflections, rather than a moving painted highlight.
 c+=float3(0.5,0.57,0.58)*pow(max(0.0,dot(d,normalize(float3(-1.0,0.65,-0.6)))),18.0);
 return c;
}
float sphereHit(float3 o,float3 d){float3 oc=o-ball;float b=dot(oc,d);float c=dot(oc,oc)-0.255*0.255;float disc=b*b-c;if(disc<0.0)return 1000.0;float t=-b-sqrt(disc);return t>0.001?t:1000.0;}
float focusLight(float2 p){
 float3 n=normalAt(p-float2(-0.45,0.4)*0.32);
 float3 nx=normalAt(p+float2(0.018,0.0)-float2(-0.45,0.4)*0.32);
 float3 nz=normalAt(p+float2(0.0,0.018)-float2(-0.45,0.4)*0.32);
 float a=1.0+(nx.x-n.x)*15.0,b=(nz.x-n.x)*15.0;
 float c=(nx.z-n.z)*15.0,d=1.0+(nz.z-n.z)*15.0;
 return clamp(0.62/max(0.13,abs(a*d-b*c)),0.25,3.7);
}
float3 tile(float3 p,float3 n){
 float2 uv=abs(n.y)>0.5?p.xz:(abs(n.x)>0.5?p.zy:p.xy);
 float2 g=abs(fract(uv*8.0)-0.5);
 float line=smoothstep(0.452,0.482,max(g.x,g.y));
 float hash=fract(sin(dot(floor(uv*8.0),float2(127.1,311.7)))*43758.5453);
 float3 c=mix(float3(0.55,0.72,0.70),float3(0.43,0.65,0.64),hash*.6);
 c=mix(c,float3(0.25,0.39,0.38),line*.8);
 float light=0.45+0.55*max(0.0,dot(n,normalize(float3(-0.45,1.0,0.4))));
 float caustic=focusLight(p.xz)*(0.55+max(0.0,n.y)*.45);
 float shadow=1.0-0.65*exp(-dot((p.xz-ball.xz-float2(.12,-.1))*3.8,(p.xz-ball.xz-float2(.12,-.1))*3.8));
 float ao=clamp(min(1.25-abs(p.x),.95-abs(p.z))*4.0,.48,1.0);
 return c*(light*.65+caustic*.52)*shadow*ao;
}
float3 underWater(float3 o,float3 d){
 float t=(-.8-o.y)/d.y;float3 n=float3(0.0,1.0,0.0);
 float tx=((d.x>0.0?1.25:-1.25)-o.x)/d.x;
 if(tx>0.001&&tx<t){t=tx;n=float3(d.x>0.0?-1.0:1.0,0.0,0.0);}
 float tz=((d.z>0.0?.95:-.95)-o.z)/d.z;
 if(tz>0.001&&tz<t){t=tz;n=float3(0.0,0.0,d.z>0.0?-1.0:1.0);}
 float ts=sphereHit(o,d);float3 c;
 if(ts<t){t=ts;float3 p=o+d*t;float3 sn=normalize(p-ball);
 float diffuse=max(0.0,dot(sn,normalize(float3(-.45,1.0,.4))));
 c=float3(.77,.89,.84)*(.25+.65*diffuse+focusLight(p.xz)*.28);
 c+=float3(.8,.9,.9)*pow(max(0.0,dot(reflect(-normalize(float3(-.45,1.0,.4)),sn),-d)),65.0)*.6;
 }else{c=tile(o+d*t,n);}
 float3 transmission=exp(-float3(.30,.075,.045)*max(t,0.0));
 return c*transmission+float3(.035,.28,.31)*(1.0-transmission);
}
half4 main(float2 frag){
 float2 uv=(frag/resolution*2.0-1.0);uv.y=-uv.y;uv.x*=resolution.x/resolution.y;
 float3 eye=float3(2.7,2.5,3.6),f=normalize(float3(0.0,-.22,0.0)-eye);
 float3 r=normalize(cross(f,float3(0.0,1.0,0.0))),u=cross(r,f);
 float3 ray=normalize(f*2.8+r*uv.x+u*uv.y);
 float t=-eye.y/ray.y;float3 p=eye+ray*t;
 float3 c=float3(.91,.925,.90);
 if(abs(p.x)<1.25&&abs(p.z)<.95){
  // Refine water intersection without high-step raymarching.
  t=(heightAt(p.xz)-eye.y)/ray.y;p=eye+ray*t;
  t+=(heightAt(p.xz)-p.y)/ray.y;p=eye+ray*t;
  float3 n=normalAt(p.xz);
  float3 rd=refract(ray,n,1.0/1.333);
  float fresnel=.02037+.97963*pow(1.0-max(0.0,dot(-ray,n)),5.0);
  c=mix(underWater(p+rd*.002,rd),sky(reflect(ray,n)),fresnel);
  c+=float3(1.0,.95,.78)*pow(max(0.0,dot(reflect(ray,n),normalize(float3(-.45,1.0,.4)))),230.0)*1.4;
 }else{
  float tr=(.045-eye.y)/ray.y;float3 pr=eye+ray*tr;
  if(abs(pr.x)<1.36&&abs(pr.z)<1.06){
   float edge=min(1.36-abs(pr.x),1.06-abs(pr.z));
   float grout=step(.485,abs(fract((abs(pr.x)>1.25?pr.z:pr.x)*4.0)-.5));
   c=float3(.78,.80,.74)*(0.9+.10*smoothstep(0.0,.03,edge))*(1.0-grout*.16);
  }else{
   float tg=(-.83-eye.y)/ray.y;float3 pg=eye+ray*tg;
   float2 q=max(abs(pg.xz)-float2(1.34,1.04),float2(0.0));
   c*=1.0-.17*exp(-dot(q,q)*13.0);
  }
 }
 c=pow(max(c,float3(0.0)),float3(.92));
 return half4(half3(c),1.0);
}
`;
export function webFragment(){return 'precision highp float;\n'+WATER_SHADER.replace('uniform shader heightmap;','uniform sampler2D heightmap;').replace(/heightmap\.eval\((lo\+float2\([^)]*\))\)/g,'texture2D(heightmap,clamp($1,float2(.5),float2(63.5,47.5))/float2(64.0,48.0))').replace(/half4 main\(float2 frag\)/,'vec4 render(vec2 frag)').replace(/\bfloat2\b/g,'vec2').replace(/\bfloat3\b/g,'vec3').replace(/\bfloat4\b/g,'vec4').replace(/\bhalf3\b/g,'vec3').replace(/\bhalf4\b/g,'vec4')+'\nvoid main(){gl_FragColor=render(vec2(gl_FragCoord.x,resolution.y-gl_FragCoord.y));}';}

import React from 'react';
import {WaterTank} from './WaterTank';
export default function Example(){return <WaterTank/>;}
